/* Google Forms enquiries are private until an administrator confirms the partner. */
const formInbox={owner:null,rows:[],partners:[],error:'',limit:100};
async function portalLoadEnquiries(){
 const owner=portal.user?.id;if(!owner)return;
 if(formInbox.owner!==owner){formInbox.owner=owner;formInbox.rows=[];formInbox.partners=[];formInbox.limit=100}
 const result=await portal.client.from('sigma_form_enquiries').select('*').order('submitted_at',{ascending:false}).range(0,formInbox.limit);
 if(portal.user?.id!==owner)return;
 formInbox.error=result.error?portalError(result.error):'';formInbox.rows=result.error?[]:result.data||[];
 if(portalModeAdmin()){const profiles=await portal.client.from('sigma_profiles').select('id,full_name,email').eq('role','partner').order('full_name');if(portal.user?.id===owner){formInbox.partners=profiles.data||[];if(profiles.error)formInbox.error=portalError(profiles.error)}}
}
function portalEnquiriesPage(){
 if(formInbox.owner!==portal.user?.id){formInbox.rows=[];formInbox.partners=[];formInbox.error='';queueMicrotask(()=>portalLoadEnquiries().then(portalRender))}
 const rows=formInbox.rows.slice(0,formInbox.limit),admin=portalModeAdmin();
 return heading('REFERRAL ENQUIRIES','Form enquiries',admin?'Review Google Form submissions and confirm which partner can see each enquiry.':'Track Google Form enquiries assigned to your account.',portalButton('Refresh','portalLoadEnquiries().then(portalRender)','renew'))+
 (admin?'<p class="notice">Partner email is supplied by the person filling the form. Confirm it before assigning access. Enquiries do not approve policies or create earnings.</p>'+portalButton('Connect Google Forms','portalFormsSetup()','lock'):'<p class="notice">Submitted forms appear here after the admin confirms your partner account. Policy uploads and earnings remain in My bookings and My statement.</p>')+
 portalInlineError(formInbox.error)+`<div class="record-grid">${rows.map(row=>`<article class="card pad"><span class="badge">${pe(row.product)}</span><h2>${pe(row.customer_name||'Customer enquiry')}</h2><p>${pe(row.customer_mobile)} · ${pe(new Date(row.submitted_at).toLocaleString())}</p>${admin?`<p>Partner email supplied: <strong>${pe(row.claimed_partner_email||'Not provided')}</strong></p>`:''}<p>${row.owner_id?'Assigned to partner':'Awaiting partner confirmation'}</p>${portalButton('View answers',`portalEnquiryDetails('${row.id}')`,'file')}${admin?portalButton(row.owner_id?'Change partner':'Assign partner',`portalEnquiryAssign('${row.id}')`,'users',true):''}</article>`).join('')||'<section class="card pad"><h2>No form enquiries yet</h2><p>Responses will appear once the Google Forms sync is connected and a form is submitted.</p></section>'}</div>${formInbox.rows.length>formInbox.limit?portalButton('Load more','formInbox.limit+=100;portalLoadEnquiries().then(portalRender)','plus'):''}`;
}
function portalEnquiryDetails(id){const row=formInbox.rows.find(r=>r.id===id);if(!row)return;modal('Enquiry · '+row.product,`<div>${row.answers.map(a=>`<section style="margin-bottom:16px"><strong>${pe(a.question)}</strong><p style="white-space:pre-wrap;overflow-wrap:anywhere">${pe(a.value||'—')}</p></section>`).join('')}</div>`)}
function portalEnquiryAssign(id){if(!portalModeAdmin())return;const row=formInbox.rows.find(r=>r.id===id);if(!row)return;modal('Confirm partner for enquiry',`<p>Check the submitted partner email: <strong>${pe(row.claimed_partner_email)}</strong>. The selected partner will be able to read all answers.</p><form onsubmit="event.preventDefault();portalEnquiryAssignSubmit('${id}',this)"><label class="field">Partner<select name="owner" required><option value="">Choose a verified partner…</option>${formInbox.partners.map(p=>`<option value="${p.id}" ${p.id===row.owner_id?'selected':''}>${pe(p.full_name)} · ${pe(p.email)}</option>`).join('')}</select></label><div class="portal-form-error" role="alert"></div><div class="modalfoot"><button type="submit" class="primary">Confirm assignment</button></div></form>`)}
async function portalEnquiryAssignSubmit(id,form){const button=form.querySelector('button');button.disabled=true;try{const result=await portal.client.rpc('sigma_assign_form_enquiry',{p_id:id,p_owner:new FormData(form).get('owner')});if(result.error)throw result.error;closeModal();await portalLoadEnquiries();portalRender();toast('Enquiry assigned to partner')}catch(e){form.querySelector('.portal-form-error').textContent=portalError(e)}finally{button.disabled=false}}
function portalFormsSetup(){if(!portalModeAdmin())return;modal('Connect Google Forms',`<p>Use the form owner’s Google Apps Script project. The script reads these four forms and sends answers privately to this dashboard.</p><ol><li>Download <a href="google-forms-sync.gs" download>Google Forms sync script</a> and paste it in a private Apps Script project.</li><li>Generate the sync key below. In Apps Script → Project Settings → Script Properties, save it as <strong>SIGMA_SYNC_KEY</strong>.</li><li>Add <strong>SUPABASE_ANON_KEY</strong> using this project’s public legacy anon JWT from Supabase API settings. Never use the service-role key.</li><li>Run <strong>sigmaInstall</strong> once and approve the Google permissions. This installs submit triggers and a five-minute retry job.</li></ol><p>Generating a new key disconnects an existing script until its property is updated.</p><div id="forms-key-result" role="status"></div><div class="modalfoot">${portalButton('Generate / replace sync key','portalFormsKey(this)','lock',true)}</div>`)}
async function portalFormsKey(button){button.disabled=true;try{const key=Array.from(crypto.getRandomValues(new Uint8Array(32))).map(n=>n.toString(16).padStart(2,'0')).join('');const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(key)))).map(n=>n.toString(16).padStart(2,'0')).join('');const result=await portal.client.rpc('sigma_set_form_sync_key',{p_hash:hash});if(result.error)throw result.error;document.querySelector('#forms-key-result').innerHTML=`<label class="field">Copy once to SIGMA_SYNC_KEY<input readonly value="${key}" onclick="this.select()"></label><p>This key is shown only here. Closing this dialog removes it from this screen.</p>`}catch(e){document.querySelector('#forms-key-result').textContent=portalError(e)}finally{button.disabled=false}}
